async function promptClockInOnLogin(){if(!state.me||state.me.role==='owner'||state.me.role==='demo')return;try{const s=await api('/api/v9/time/status');if(s.open)return;openModal('⏰ Start Your SBC Work Session',`<div class="clock-login-prompt"><div class="eyebrow">WELCOME BACK, ${esc(state.me.name||'TEAM MEMBER')}</div><h2>Before you start, clock in.</h2><p>Your work time is recorded by the SBC Time Clock. Choose what you are starting with now.</p><div class="grid two"><button class="stat" onclick="clockInFromLogin('training')"><strong>🎓 Training</strong><div class="mini">Training Center, onboarding or practice.</div></button><button class="stat" onclick="clockInFromLogin('calling')"><strong>☎️ Calling / Work</strong><div class="mini">Sales calls or approved production work.</div></button></div><p class="mini" style="margin-top:14px">If you are not working yet, close this window. SBC will ask again the next time you sign in while you are off the clock.</p></div>`)}catch(e){}}
let clockActionBusy=false;
async function refreshTimeClock(){
  const s=await api('/api/v9/time/status',{timeoutMs:15000});
  if(state.data) state.data.timeEntries=Array.isArray(s.entries)?s.entries:[];
  return s;
}
async function clockAction(action,mode='training'){
  if(clockActionBusy)return;
  clockActionBusy=true;
  try{
    const safeMode=['training','calling','admin'].includes(String(mode))?String(mode):'training';
    const requested=String(action);
    let r;
    try{
      r=await api('/api/v9/time/clock',{method:'POST',body:JSON.stringify({action:requested,mode:safeMode,requestId:'clock-'+Date.now()}) ,timeoutMs:30000});
    }catch(primary){
      // Mobile networks can lose the response after the server has already committed the clock action.
      // Re-read authoritative state before reporting failure.
      try{
        const status=await refreshTimeClock();
        const open=!!status.open;
        if((requested==='in'&&open)||(requested==='out'&&!open)||(requested==='break_start'&&status.open?.activeBreak)||(requested==='break_end'&&status.open&&!status.open.activeBreak)){
          render();
          toast(requested==='in'?'Clocked in ✓':requested==='out'?'Clocked out ✓':requested==='break_start'?'Break started ✓':'Break ended ✓');
          return status.open||{};
        }
      }catch(_verify){}
      throw primary;
    }
    await refreshTimeClock();
    render();
    toast(requested==='in'?'Clocked in ✓':requested==='out'?'Clocked out ✓':requested==='break_start'?'Break started ✓':'Break ended ✓');
    return r;
  }catch(e){
    try{await refreshTimeClock();render();}catch(_){}
    toast(e.message||'Time Clock action failed.');
    throw e;
  }finally{clockActionBusy=false;}
}

async function clockInFromLogin(mode){try{await clockAction('in',mode);closeModal();state.view=mode==='calling'?'callcenter':'training';render();toast('Clocked in ✓')}catch(e){toast(e.message)}}
