async function load(){
  state.data=await api('/api/bootstrap',{timeoutMs:18000});
  const [mtResult,trainingResult]=await Promise.allSettled([
    api('/api/message-templates',{timeoutMs:15000}),
    api('/api/training',{timeoutMs:20000})
  ]);
  if(mtResult.status==='fulfilled') state.data.messageTemplates=Array.isArray(mtResult.value?.templates)?mtResult.value.templates:[];
  else {console.warn('[SBC MESSAGE TEMPLATES] unavailable during bootstrap:',mtResult.reason?.message||mtResult.reason);state.data.messageTemplates=Array.isArray(state.data.messageTemplates)?state.data.messageTemplates:[];}
  if(trainingResult.status==='fulfilled') state.data.trainingCenter=trainingResult.value;
  else {console.warn('[SBC TRAINING] unavailable during bootstrap:',trainingResult.reason?.message||trainingResult.reason);state.data.trainingCenter={ok:false,assigned:[],available:[],progress:[],attempts:[],certifications:[],history:[]};}
  const authoritativeCustomers=(state.data.customers||[]).map(canonicalCustomer);
let recoveryLeads=Array.isArray(state.data.recoveryProjection)
  ? state.data.recoveryProjection.filter(x=>x && x._recoveryProjection && !x._restored).map(canonicalCustomer)
  : [];
// V65.1.23: if bootstrap raced recovery evaluation or an older renderer supplied an empty CRM,
// perform one explicit owner read-only projection fetch. This NEVER restores or mutates CRM rows.
if(!recoveryLeads.length && !authoritativeCustomers.length && state.me?.role==='owner') {
  try {
    const rp=await api('/api/owner/recovery/leads',{timeoutMs:10000});
    if(Array.isArray(rp.records)) recoveryLeads=rp.records.filter(x=>x && x._recoveryProjection && !x._restored).map(canonicalCustomer);
    state.data.recoveryProjection=rp.records||[];
    state.data.recovery=state.data.recovery||{};
    state.data.recovery.required=Boolean(rp.readOnly||rp.authoritative===false);
    state.data.recovery.recoveryProjection={source:rp.source||'sbc_lead_mesh',records:recoveryLeads.length,readOnly:true,authoritative:false};
  } catch(e) { console.warn('[SBC RECOVERY PROJECTION] read-only fetch unavailable:',e?.message||e); }
}
state.data.customers=[...recoveryLeads,...authoritativeCustomers.filter(c=>!recoveryLeads.some(r=>String(r._leadMeshId||'')===String(c._leadMeshId||'')))];
state.__recoveryLeadCount=recoveryLeads.length;
const catalogCandidate=state.data?.catalog&&typeof state.data.catalog==='object'?state.data.catalog:{};state.catalog={...catalogCandidate,packages:Array.isArray(catalogCandidate.packages)?catalogCandidate.packages:(Array.isArray(state.data?.packages)?state.data.packages:[]),services:Array.isArray(catalogCandidate.services)?catalogCandidate.services:[]};if(window.injectV9Nav)window.injectV9Nav();bindSbcPrimaryNav();if(state.me?.role==='caller'&&!['callcenter','customers'].includes(state.view))state.view='callcenter';$('#storageLabel').textContent=`Private SBC workspace · ${state.data.storage.startsWith('mysql')?'MySQL database':'persistent file storage'}`;render();
}
