function sbcKimMessage(role,text){const box=document.getElementById('sbcAiMessages');if(!box)return;const row=document.createElement('div');row.className='sbc-kim-message '+(role==='user'?'user':'assistant');const bubble=document.createElement('div');bubble.className='sbc-kim-bubble';const content=document.createElement('div');content.className='sbc-kim-message-text';content.textContent=String(text??'');bubble.appendChild(content);if(role!=='user'){const actions=document.createElement('div');actions.className='sbc-kim-message-actions';const b=document.createElement('button');b.type='button';b.className='sbc-kim-mini-action';b.textContent='🔊';b.title='Read aloud';b.onclick=()=>sbcSpeakKim(String(text??''),b);actions.appendChild(b);bubble.appendChild(actions);}row.appendChild(bubble);box.appendChild(row);box.scrollTop=box.scrollHeight;return row;}
async function sbcSpeakKim(text,button){
  const clean=String(text||'').trim().slice(0,5000);if(!clean)return;
  try{
    if(window.sbcKimAudio){try{window.sbcKimAudio.pause();window.sbcKimAudio.currentTime=0;}catch{}}
    const status=document.getElementById('sbcAiVoiceStatus');if(status)status.textContent='Speaking…';if(button)button.disabled=true;
    const selected=localStorage.getItem('sbc.kim.voice')||'coral';
    const r=await fetch('/api/ai/tts',{method:'POST',credentials:'include',headers:{'Content-Type':'application/json'},body:JSON.stringify({text:clean,voice:selected})});
    if(!r.ok){let j={};try{j=await r.json()}catch{}throw new Error(j.error||`Voice request failed (${r.status})`);}
    const blob=await r.blob();const url=URL.createObjectURL(blob);const audio=new Audio(url);window.sbcKimAudio=audio;
    audio.onended=()=>{URL.revokeObjectURL(url);if(status)status.textContent=`Kim voice: ${selected}`;if(button)button.disabled=false;};
    audio.onerror=()=>{URL.revokeObjectURL(url);if(status)status.textContent='Kim voice playback error';if(button)button.disabled=false;};
    await audio.play();
  }catch(e){
    const s=document.getElementById('sbcAiVoiceStatus');if(s)s.textContent=`Kim voice unavailable: ${e.message||'TTS failed'}`;
    if(button)button.disabled=false;
  }
}
