async function loadOpsHardening(){
  const mount=$('#opsHardeningMount');if(!mount)return;
  try{
    const o=await api('/api/ops/overview');
    const q=o.counts?.quality||{}, p=o.pipeline||{}, perf=o.performance||[], audit=o.audit||[], perms=o.permissions||[];
    const matrix=o.permissionMatrix||{};
    const roleLabel={owner:'Owner',manager:'Manager',caller:'Sales Account Manager',lead_researcher:'Lead Researcher',fulfillment:'Fulfillment Specialist'};
    const stages=['New Lead','Verified','Sales Ready','Contacted','Qualified','Proposal','Won','Fulfillment','Customer','Lost'];
    const perfHtml=perf.length?perf.map(x=>`<div class="list-card"><div><strong>${esc(x.name)}</strong><div class="meta">${esc(roleLabel[x.role]||x.role)}</div><div class="mini">Today: ${x.today?.hours||0}h · ${x.today?.leads||0} leads · ${x.today?.calls||0} calls · ${x.today?.sales||0} sales · ${x.today?.wonOrders||0} paid/active orders</div><div class="mini">7d: ${x.week.hours}h · ${x.week.leads} leads · ${x.week.calls} calls · ${x.week.sales} sales · ${x.week.wonOrders} paid/active orders</div><div class="mini">30d: ${x.month.hours}h · ${x.month.leads} leads · ${x.month.calls} calls · ${x.month.sales} sales</div></div><span class="badge blue">${x.week.openTasks} open tasks</span></div>`).join(''):'<div class="empty">Performance telemetry is visible to the owner/manager role only.</div>';
    const auditHtml=audit.slice(0,12).map(x=>`<div class="list-card"><div><strong>${esc(x.type||'event')}</strong><div class="meta">${esc(x.userName||'System')} · ${new Date(x.createdAt).toLocaleString()}</div><div class="mini">${esc(x.message||'')}</div></div></div>`).join('')||'<div class="empty">No audit activity yet.</div>';
    const matrixHtml=Object.entries(matrix).map(([role,items])=>`<div class="list-card"><div><strong>${esc(roleLabel[role]||role)}</strong><div class="mini">${esc(items.join(' · '))}</div></div></div>`).join('');
    mount.innerHTML=`<div class="card-head"><div><h2>🛡️ Operations Hardening · V30</h2><div class="mini">The final operating layer: security, duplicate control, pipeline discipline, performance telemetry, data cleansing and Kim visibility.</div></div><span class="badge green">LIVE CONTROL LAYER</span></div><div class="card-body"><div class="grid four"><div class="stat"><div class="label">DUPLICATE GROUPS</div><div class="value">${o.counts?.duplicates||0}</div><div class="sub">Server-side duplicate scan</div></div><div class="stat"><div class="label">AVG LEAD QUALITY</div><div class="value">${q.averageScore||0}</div><div class="sub">Data-readiness score / 100</div></div><div class="stat"><div class="label">INCOMPLETE LEADS</div><div class="value">${q.incomplete||0}</div><div class="sub">Missing core data</div></div><div class="stat"><div class="label">YOUR PERMISSIONS</div><div class="value" style="font-size:18px">${perms.length}</div><div class="sub">Server-enforced capabilities</div></div></div><div class="actions" style="margin-top:14px"><button class="btn primary" onclick="opsOpenPipeline()">🎯 Open Pipeline Board</button><button class="btn" onclick="opsScanDuplicates()">🔎 Scan Duplicates</button>${o.cleanse?.available?`<button class="btn" onclick="opsCleanseLeads()">🧹 Cleanse / Normalize Leads</button>`:''}<button class="btn" onclick="openSbcAI('Review the V30 Operations Hardening layer. Check duplicate signals, lead quality, pipeline flow, team activity and recent audit events. Tell me what needs attention.')">🤖 Ask Kim to Review</button><button class="btn" onclick="opsRunSafetyHarness()">🧪 Run Safety Harness</button></div><div class="card" style="margin-top:16px"><div class="card-head"><div><h3>🎯 Visual Lead Pipeline</h3><div class="mini">Move leads through documented stages instead of relying on free-form status changes.</div></div></div><div class="card-body"><div style="display:flex;gap:10px;overflow:auto;padding-bottom:4px">${stages.map(s=>opsStagePill(s,p[s])).join('')}</div></div></div><div class="grid two" style="margin-top:16px"><div class="card"><div class="card-head"><h3>🧹 Lead Quality</h3><span class="badge blue">DATA READINESS</span></div><div class="card-body"><div class="mini">Hot ${q.hot||0} · Warm ${q.warm||0} · Cold ${q.cold||0} · Average ${q.averageScore||0}/100</div><p>Normalization standardizes phone/email/website fields, recalculates quality and preserves the lead's documented facts. No outside data is invented.</p></div></div><div class="card"><div class="card-head"><h3>🚫 Duplicate Protection</h3><span class="badge green">SERVER ENFORCED</span></div><div class="card-body"><p>New lead/customer creation now checks normalized phone, email and business identity before writing. Existing duplicates can be surfaced for review without automatically deleting records.</p></div></div></div><div class="card" style="margin-top:16px"><div class="card-head"><div><h3>📊 Team Performance</h3><div class="mini">Evidence-based workload telemetry; not a ranking.</div></div></div><div class="card-body">${perfHtml}</div></div><div class="grid two" style="margin-top:16px"><div class="card"><div class="card-head"><h3>🔐 RBAC / Permissions</h3><span class="badge green">SERVER ENFORCED</span></div><div class="card-body"><div class="install-tip"><strong>Your role:</strong> ${esc(roleLabel[o.user?.role]||o.user?.role||'Team Member')}<br><strong>Active permissions:</strong> ${esc(perms.join(' · ')||'None')}</div>${o.user?.role==='owner'?`<div style="margin-top:12px">${matrixHtml}</div>`:''}</div></div><div class="card"><div class="card-head"><h3>📝 Recent Audit Trail</h3><span class="badge blue">TRACEABLE</span></div><div class="card-body">${auditHtml}</div></div></div></div>`;
  }catch(e){mount.innerHTML=`<div class="card-body"><div class="install-tip">Operations Hardening could not load: ${esc(e.message||e)}</div><button class="btn" onclick="loadOpsHardening()">Retry</button></div>`;}
}
async function opsScanDuplicates(){try{const r=await api('/api/ops/duplicates');if(!r.groups?.length){toast('Duplicate scan clear — no duplicate groups found in your visible lead pool.');return;}const rows=r.groups.slice(0,40).map(g=>`<div class="list-card"><div><strong>${esc(g.reasons)} match</strong><div class="mini">${g.records.map(x=>`${esc(x.businessName||'Unnamed')} · ${esc(x.phone||'')} · ${esc(x.email||'')}`).join('<br>')}</div></div></div>`).join('');openModal('🔎 Duplicate Lead Review',`<div class="card-body"><p>${r.count} duplicate group(s) detected. Nothing was deleted automatically.</p>${rows}<div class="actions"><button class="btn" onclick="closeModal()">Close</button><button class="btn primary" onclick="closeModal();state.view='customers';render()">Open Leads</button></div></div>`)}catch(e){toast(e.message||'Duplicate scan failed')}}
async function opsCleanseLeads(){if(!confirm('Normalize visible lead data now? This standardizes formatting and recalculates quality; it does not invent missing facts.'))return;try{const r=await api('/api/ops/leads/cleanse',{method:'POST',body:'{}'});toast(`Lead cleanse complete · ${r.changed} changed of ${r.reviewed} reviewed`);await loadOpsHardening();}catch(e){toast(e.message||'Lead cleansing failed')}}
async function opsOpenPipeline(){try{const r=await api('/api/ops/pipeline');const stages=r.stages||[];const grouped=Object.fromEntries(stages.map(x=>[x,[]]));(r.leads||[]).forEach(x=>(grouped[x.pipelineStage]||(grouped[x.pipelineStage]=[])).push(x));const canMove=['owner','manager','caller','lead_researcher'].includes(state.me?.role);const cards=stages.map(stage=>`<div class="card" style="min-width:250px;flex:1"><div class="card-head"><h3>${esc(stage)}</h3><span class="badge blue">${grouped[stage]?.length||0}</span></div><div class="card-body">${(grouped[stage]||[]).slice(0,30).map(c=>`<div class="list-card" style="display:block"><strong>${esc(c.businessName)}</strong><div class="mini">${esc(c.contactName||'No contact')} · ${esc(c.phone||'')}</div>${canMove?`<select style="margin-top:8px;width:100%" onchange="opsMovePipeline('${esc(c.id)}',this.value)">${stages.map(x=>`<option ${x===stage?'selected':''}>${esc(x)}</option>`).join('')}</select>`:''}</div>`).join('')||'<div class="empty">No leads here.</div>'}</div></div>`).join('');openModal('🎯 SBC Lead Pipeline Board',`<div class="mini" style="margin-bottom:12px">Stages are server-controlled. Researchers stay in research/verification stages; sales callers can advance assigned sales stages; owner/manager can manage the full pipeline.</div><div style="display:flex;gap:12px;overflow:auto;align-items:flex-start">${cards}</div><div class="actions" style="margin-top:14px"><button class="btn" onclick="closeModal()">Close</button></div>`)}catch(e){toast(e.message||'Pipeline could not load')}}
async function opsMovePipeline(id,stage){try{await api('/api/ops/pipeline/'+encodeURIComponent(id),{method:'POST',body:JSON.stringify({stage})});toast(`Pipeline moved to ${stage}`);closeModal();opsOpenPipeline();loadOpsHardening();}catch(e){toast(e.message||'Pipeline update failed')}}

