function dashboard(){const isSyntheticTestCustomer=x=>{if(!x||typeof x!=='object')return false;const n=String(x.businessName||x.business_name||x.name||'').trim().toLowerCase(),src=String(x.source||'').toLowerCase(),notes=String(x.notes||'').toLowerCase();return n==='sbc system test — do not service'||n==='sbc system test - do not service'||/sbc system test|sbc full-cycle test|v47 full-cycle test|do not service/.test(src+' '+notes);};const d=state.data||{},c=Array.isArray(d.customers)?d.customers:[],projected=c.filter(x=>x&&!isSyntheticTestCustomer(x)&&x._recoveryProjection),authoritative=c.filter(x=>!x?false:!x._recoveryProjection),recovery=Boolean(d.recovery?.required),q=Array.isArray(d.quotes)?d.quotes:[],o=Array.isArray(d.orders)?d.orders:[],r=Array.isArray(d.renewals)?d.renewals:[],activities=Array.isArray(d.activities)?d.activities:[];const won=q.filter(x=>['Won','Paid'].includes(x.status));const pipeline=q.filter(x=>!['Lost','Paid','Won'].includes(x.status)).reduce((a,x)=>a+x.total,0);const revenue=won.reduce((a,x)=>a+x.total,0);const overdue=c.filter(x=>x.followUp&&x.followUp<today()).length;const renewSoon=r.filter(x=>x.status!=='Paid'&&x.dueDate>=today()&&x.dueDate<=new Date(Date.now()+30*864e5).toISOString().slice(0,10)).length;return `<div class="hero"><div><div class="eyebrow" style="color:#f7a842">SUCCESSFUL BY CHOICE · ${esc(state.me?.role==='lead_researcher'?'LEAD RESEARCH':'COMMAND CENTER')}</div><h2>Run the business. Don't just chase the business.</h2><p>Your private operating center for leads, customers, quotes, payments, print orders, renewals and follow-ups.</p></div><div class="hero-actions" ${state.me?.role==='demo'?'style="display:none!important"':''}><button class="btn orange" onclick="newCustomer()">+ New Lead</button>${state.me?.role==='owner'?'<a class="btn ghost" href="/owner/lead-import" data-sbc-owner-lead-import="true">Import 31 Leads</a>':''}<button class="btn ghost" onclick="newQuote()">Create Quote</button><button class="btn ghost" onclick="newOrder()">New Print Order</button><button class="btn ghost" onclick="state.view='presentation';render()">Customer Presentation</button></div></div><div id="sbcProductionControlDashboard" class="card section"><div class="card-body">Loading production control…</div></div><div class="card section ai-role-briefing"><div id="sbcRoleBriefing">${state.aiBriefing?renderRoleBriefing(state.aiBriefing):'<div class="mini">🤖 Kim is available when you open AI. The core Command Center does not depend on the AI connection.</div><div class="actions"><button class="btn small" onclick="openSbcAI()">Open Kim</button></div>'}</div></div><div class="grid stats"><div class="stat"><div class="label">${recovery?'PRESERVED LEAD CANDIDATES':'ACTIVE LEADS'}</div><div class="value">${recovery?projected.length:c.filter(x=>!isSyntheticTestCustomer(x)&&!['Customer','Lost','Do Not Call','Closed','Duplicate','Not Qualified'].includes(String(x.status||''))).length}</div><div class="sub">${recovery?`${projected.length} read-only lead-mesh rows · ${authoritative.length} current CRM rows in app memory`:`${c.length} total CRM records`}</div></div><div class="stat"><div class="label">OPEN PIPELINE</div><div class="value">${money(pipeline)}</div><div class="sub">Quoted opportunities</div></div><div class="stat"><div class="label">WON / PAID</div><div class="value">${money(revenue)}</div><div class="sub">Recorded revenue</div></div><div class="stat"><div class="label">OVERDUE FOLLOW-UPS</div><div class="value">${overdue}</div><div class="sub">Needs attention</div></div><div class="stat"><div class="label">RENEWALS · 30 DAYS</div><div class="value">${renewSoon}</div><div class="sub">Recurring revenue opportunities</div></div></div><div class="grid two section"><div class="card ecosystem-digital"><div class="card-head"><div><h2>💻 Digital Pipeline</h2><div class="mini">Websites, domains, hosting, email, Google visibility, security and related digital delivery.</div></div><span class="badge blue">OPERATIONS</span></div><div class="card-body"><div class="grid two"><div class="stat"><div class="label">OPEN ORDERS</div><div class="value">${Number(d.ecosystem?.orderPipelines?.digital?.orders||0)}</div><div class="sub">Digital production orders</div></div><div class="stat"><div class="label">ORDER VALUE</div><div class="value">${money(d.ecosystem?.orderPipelines?.digital?.value||0)}</div><div class="sub">Current digital order value</div></div></div><div class="actions"><button class="btn small" onclick="state.view='orders';render()">Open Digital / Print Orders</button></div></div></div><div class="card ecosystem-print"><div class="card-head"><div><h2>🖨️ Print Production Pipeline</h2><div class="mini">Business cards, flyers, banners, apparel and other physical fulfillment.</div></div><span class="badge orange">EASY ADD-ON</span></div><div class="card-body"><div class="grid two"><div class="stat"><div class="label">OPEN ORDERS</div><div class="value">${Number(d.ecosystem?.orderPipelines?.print?.orders||0)}</div><div class="sub">Print production orders</div></div><div class="stat"><div class="label">ORDER VALUE</div><div class="value">${money(d.ecosystem?.orderPipelines?.print?.value||0)}</div><div class="sub">Current print order value</div></div></div><div class="install-tip"><strong>💳 Business cards:</strong> Keep asking. They are an easy standalone sale and a natural add-on to digital packages.</div></div></div></div><div class="card"><div class="card-head"><h2>Quote Pipeline</h2><div class="actions" style="margin:0"><button class="btn small" onclick="state.view='quotes';render()">Open quotes</button></div></div><div class="card-body"><div class="pipeline">${['Draft','Sent','Won','Paid','Lost'].map(s=>{const a=q.filter(x=>x.status===s);return `<div class="pipe"><strong>${s}</strong><span>${a.length}</span><small class="mini">${money(a.reduce((v,x)=>v+x.total,0))}</small></div>`}).join('')}</div></div></div><div class="card"><div class="card-head"><h2>Upcoming attention</h2></div><div class="card-body"><div class="list-card"><div><div class="title">${overdue} overdue follow-ups</div><div class="meta">Keep the sales conversation moving.</div></div><button class="btn small" onclick="state.view='followups';render()">Open</button></div><div class="list-card"><div><div class="title">${renewSoon} renewals in 30 days</div><div class="meta">Potential recurring revenue.</div></div><button class="btn small" onclick="state.view='renewals';render()">Open</button></div><div class="list-card"><div><div class="title">${Number(d.ecosystem?.orderPipelines?.print?.orders||0)} print orders open</div><div class="meta">Keep fulfillment on schedule.</div></div><button class="btn small" onclick="state.view='orders';render()">Open</button></div></div></div></div><div class="grid two section"><div class="card"><div class="card-head"><h2>Recent activity</h2></div><div class="card-body"><div class="activity">${activities.filter((a,i,all)=>all.findIndex(x=>String(x.type)===String(a.type)&&String(x.message)===String(a.message))===i).slice(0,8).map(a=>`<div class="activity-row"><div class="activity-icon">${a.type==='quote'?'$':a.type==='order'?'▥':a.type==='renewal'?'↻':'•'}</div><div><strong>${esc(a.message)}</strong><small>${dt(a.createdAt)}</small></div></div>`).join('')||'<div class="empty">Your activity feed will appear here.</div>'}</div></div></div><div class="card"><div class="card-head"><h2>Top SBC packages</h2><span class="badge blue">Customer pricing</span></div><div class="card-body">${(Array.isArray(state.catalog?.packages)?state.catalog.packages:[]).map(p=>`<div style="margin-bottom:14px"><div style="display:flex;justify-content:space-between;font-size:12px;font-weight:800;margin-bottom:6px"><span>${esc(p.name)}</span><span>${money(p.price)}</span></div><div class="progress"><i style="width:${Math.min(100,p.price/10)}%"></i></div></div>`).join('')}</div></div></div>`}
function customers(){const list=state.data.customers||[];const recovery=Boolean(state.data.recovery?.required)||list.some(x=>x?._recoveryProjection);const projectionCount=list.filter(x=>x?._recoveryProjection).length;const authoritativeCount=list.filter(x=>!x?._recoveryProjection).length;const caller=state.me?.role==='caller';return `${recovery?`<div class="install-tip recovery-projection-banner"><strong>RECOVERY LOCK ACTIVE — ${projectionCount} preserved lead-mesh candidates</strong><div>These records are visible for reference only. They are not counted as verified Sales Ready leads, cannot be edited or contacted from this screen, and have not been promoted into the authoritative CRM. Current CRM rows in this view: ${authoritativeCount}. Reconcile the authoritative backup before restoring or enabling outreach.</div></div>`:''}<div class="card"><div class="card-head"><div class="toolbar"><input id="customerSearch" placeholder="Search business, name, phone, email or industry…"><select id="customerStatus"><option value="">All statuses</option><option>Lead</option><option>Contacted</option><option>Qualified</option><option>Customer</option><option>Lost</option></select><select id="customerTemperature"><option value="">All temperatures</option><option value="Hot">🔥 Hot</option><option value="Warm">🟠 Warm</option><option value="Cold">🔵 Cold</option></select></div><div class="actions" style="margin:0">${caller?'':(recovery?'<button class="btn" type="button" onclick="window.sbcRecoveryRefreshLeads?.()">↻ Refresh preserved leads</button>':'<button class="btn" onclick="auditLeadPool()">🔎 Audit & Sort Leads</button><button class="btn danger" id="deleteSelectedCustomers" disabled onclick="deleteSelectedCustomers()">Delete Selected (0)</button><button class="btn primary" onclick="newCustomer()">+ Add Customer</button>')}</div></div><div class="lead-quality-summary"><strong>${recovery?'Visible preserved candidates (read-only):':'Active Sales Leads:'}</strong> ${recovery?projectionCount:list.filter(isActiveSalesLead).length} · <span>${recovery?`${authoritativeCount} current CRM rows · ${projectionCount} non-authoritative projection rows`:`${list.length} total CRM records`}</span> · <span>Rendering max ${CUSTOMER_RENDER_LIMIT} rows at a time.</span> · <span>Hot ${list.filter(x=>isActiveSalesLead(x)&&x.leadTemperature==='Hot').length}</span> · <span>Warm ${list.filter(x=>isActiveSalesLead(x)&&x.leadTemperature==='Warm').length}</span> · <span>Cold ${list.filter(x=>isActiveSalesLead(x)&&x.leadTemperature==='Cold').length}</span><span class="mini">Temperature reflects verified data/completeness and documented opportunity — not a promise of buying intent.</span></div><div class="table-wrap"><table class="table"><thead><tr>${caller?'':'<th><input type="checkbox" id="selectAllCustomers"></th>'}<th>Business Name</th><th>Contact</th><th>Phone</th><th>Email</th><th>Website</th><th>Type</th><th>Quality</th><th>Status</th><th>Source</th><th>Follow-up</th><th></th></tr></thead><tbody id="customerRows">${customerRows(list)}</tbody></table></div></div>`}

const CUSTOMER_RENDER_LIMIT=50;
function customerRows(list){const caller=state.me?.role==='caller';const rows=Array.isArray(list)?list.slice(0,CUSTOMER_RENDER_LIMIT):[];return rows.length?rows.map(c=>{const projected=Boolean(c?._recoveryProjection);return `<tr class="${projected?'recovery-projection-row':''}">${caller||projected?'':'<td><input type="checkbox" class="customer-select" value="'+esc(c.id)+'"></td>'}<td>${projected?`<button type="button" class="link-button" title="View preserved read-only lead" onclick="openRecoveryLeadReadOnly('${esc(c.id)}')">${esc(c.businessName||'—')}</button>`:`<button type="button" class="link-button" title="Open Customer 360" onclick="openCustomer360Safe('${esc(c.id)}')">${esc(c.businessName||'—')}</button>`}</td><td>${esc(c.contactName||'—')}</td><td>${esc(c.phone||'—')}</td><td>${esc(c.email||'—')}</td><td>${esc(c.website||c.websiteStatus||'—')}</td><td>${esc(c.industry||'—')}</td><td>${projected?'<span class="badge orange">Recovery · Read only</span>':leadQualityBadge(c)}</td><td>${projected?'<span class="badge orange">Needs verification</span>':badge(c.status)}</td><td>${esc(c.source||'—')}</td><td>${c.followUp?date(c.followUp):'—'}</td><td>${projected?'<span class="mini">No outreach or edits during recovery</span>':caller?`<button type="button" class="btn small primary" onclick="openSbcDialer('${esc(c.id)}')">☎ Call</button> <button type="button" class="btn small" onclick="openCallerAccount('${esc(c.id)}')">Account</button>`:`<button type="button" class="btn small primary" onclick="openCustomer360Safe('${esc(c.id)}')">Open</button> <button type="button" class="btn small" onclick="openPortalCustomerDirect('${esc(c.id)}')">Portal</button> <button type="button" class="btn small danger" onclick="deleteCustomer('${esc(c.id)}')">Delete</button>`}</td></tr>`}).join(''):'<tr><td colspan="12"><div class="empty">No leads available.</div></td></tr>'}
function isActiveSalesLead(c){return !['Customer','Lost','Do Not Call','Closed','Duplicate','Not Qualified'].includes(String(c?.status||'Lead'));}
function leadQualityBadge(c){const t=c.leadTemperature||'Cold';const cls=t==='Hot'?'green':t==='Warm'?'orange':'blue';return `<span class="badge ${cls}" title="Data-quality score ${Number(c.leadScore||0)}/100">${t} · ${Number(c.leadScore||0)}</span>`}
async function opsRunSafetyHarness(){try{const r=await api('/api/ops/safety-harness',{method:'POST',body:JSON.stringify({})});const rows=(r.results||[]).map(x=>`<div class="list-card"><div><strong>${esc(x.name)}</strong><div class="mini">${esc(x.detail)}</div></div><span class="badge ${x.status==='PASS'?'green':'red'}">${esc(x.status)}</span></div>`).join('');openModal('V30 Production Safety Harness',`<div class="detail-box"><strong>${r.ok?'🟢 ALL CONTROLLED TESTS PASSED':'🔴 CONTROLLED TEST FAILURE'}</strong><div class="mini">${r.summary?.passed||0} passed · ${r.summary?.failed||0} failed · ${r.mutations||0} production mutations</div></div><div class="list">${rows}</div><div class="install-tip">${esc(r.note||'Synthetic defensive tests only; no live traffic spike or payment was sent.')}</div>`);toast(r.ok?'Safety harness passed':'Safety harness found a failure')}catch(e){toast(e.message)}}
async function auditLeadPool(){try{const r=await api('/api/crm/leads/audit',{method:'POST',body:JSON.stringify({dedupe:true,rate:true})});await load();toast(`Lead audit complete: ${r.total} reviewed · ${r.removedDuplicates} duplicate records removed`);}catch(e){toast(e.message)}}
function openRecoveryLeadReadOnly(id){const c=(state.data?.customers||[]).find(x=>String(x.id)===String(id)&&x._recoveryProjection);if(!c){toast('Preserved lead is not loaded. Refresh the lead list.');return}openModal('Preserved Lead — Read Only',`<div class="detail-box"><strong>${esc(c.businessName||'Unnamed business')}</strong><div class="mini">Source: ${esc(c.source||'sbc_lead_mesh')} · Status: ${esc(c._recoveryStatus||'PENDING_VERIFICATION')}</div></div><div class="form-grid"><label>Contact<input readonly value="${esc(c.contactName||'')}"></label><label>Phone<input readonly value="${esc(c.phone||'')}"></label><label>Email<input readonly value="${esc(c.email||'')}"></label><label>Website<input readonly value="${esc(c.website||'')}"></label><label>Industry<input readonly value="${esc(c.industry||'')}"></label><label>Address<input readonly value="${esc(c.address||'')}"></label></div><div class="install-tip" style="margin-top:14px">Recovery lock active. This record is a preserved lead-mesh candidate, not an authoritative CRM customer. Do not contact, edit, delete, or promote it until source provenance is reconciled.</div><div class="actions"><button type="button" class="btn primary" onclick="closeModal()">Close</button></div>`)}
window.openRecoveryLeadReadOnly=openRecoveryLeadReadOnly;window.sbcRecoveryRefreshLeads=async function(){try{await load();toast('Preserved lead projection refreshed; no CRM writes performed.')}catch(e){toast(e.message)}};

function newCustomer(existing={}){const c=existing;openModal(c.id?'Edit customer':'New lead',`<form id="customerForm"><div class="form-grid"><label>Business name<input name="businessName" value="${esc(c.businessName)}" placeholder="ABC Cleaning LLC"></label><label>Contact name<input name="contactName" value="${esc(c.contactName)}" placeholder="Owner / decision maker"></label><label>Phone<input name="phone" value="${esc(c.phone)}"></label><label>Email<input type="email" name="email" value="${esc(c.email)}"></label><label>Website<input name="website" value="${esc(c.website||'')}" placeholder="https://example.com"></label><label>Type / Industry<input name="industry" value="${esc(c.industry||'')}" placeholder="Salon, Landscaping, Roofing…"></label><label>Status<select name="status">${['Lead','Contacted','Qualified','Customer','Lost'].map(x=>`<option ${c.status===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Lead source<select name="source">${['Walk-in','Client Findr','Google','Referral','Website','Phone','Instagram','Other'].map(x=>`<option ${c.source===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Follow-up date<input type="date" name="followUp" value="${esc(c.followUp)}"></label><label>Notes<textarea name="notes" placeholder="Needs website, cards, hosting, etc.">${esc(c.notes)}</textarea></label></div><div class="actions"><button type="button" class="btn" onclick="closeModal()">Cancel</button>${c.id?`<button type="button" class="btn danger" onclick="deleteCustomer('${c.id}')">Delete</button>`:''}<button class="btn primary">Save customer</button></div></form>`);$('#customerForm').onsubmit=async e=>{e.preventDefault();const p=Object.fromEntries(new FormData(e.target).entries());try{await api(c.id?'/api/customers/'+c.id:'/api/customers',{method:c.id?'PUT':'POST',body:JSON.stringify(p)});closeModal();await load();toast(c.id?'Customer updated':'Customer added')}catch(x){toast(x.message)}}}
function addAccountNote(id){const c=state.data.customers.find(x=>x.id===id);if(!c)return;const html='<form id="accountNoteForm"><div class="detail-box"><strong>'+esc(c.businessName||c.contactName||'Account')+'</strong><div class="mini">This note is saved directly to the account and remains available to the SBC team.</div></div><label>Account note<textarea name="note" required maxlength="3000" placeholder="What happened? What did the customer say? What needs to happen next?"></textarea></label><div class="actions"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button class="btn primary">Save Account Note</button></div></form>';openModal('Add Account Note',html);$('#accountNoteForm').onsubmit=async e=>{e.preventDefault();try{await api('/api/customers/'+id+'/account-notes',{method:'POST',body:JSON.stringify({note:e.target.note.value})});closeModal();await load();if(state.me?.role==='caller')callerLead(id);else openLead(id);toast('Account note saved')}catch(x){toast(x.message)}}}
function editCustomer(id){const c=state.data.customers.find(x=>x.id===id);if(c)newCustomer(c)}
async function deleteCustomer(id){if(!confirm('Delete this customer?'))return;try{await api('/api/customers/'+id,{method:'DELETE'});closeModal();await load();toast('Customer deleted')}catch(e){toast(e.message)}}
async function deleteSelectedCustomers(){const ids=[...document.querySelectorAll('.customer-select:checked')].map(x=>x.value);if(!ids.length)return;if(!confirm(`Delete ${ids.length} selected lead${ids.length===1?'':'s'}? This cannot be undone.`))return;try{await api('/api/customers/bulk-delete',{method:'POST',body:JSON.stringify({ids})});await load();toast(`${ids.length} lead${ids.length===1?'':'s'} deleted`)}catch(e){toast(e.message)}}
function bindCustomerSelection(){const all=$('#selectAllCustomers'),btn=$('#deleteSelectedCustomers');const update=()=>{const boxes=$$('.customer-select'),checked=boxes.filter(x=>x.checked);if(all){all.checked=boxes.length>0&&checked.length===boxes.length;all.indeterminate=checked.length>0&&checked.length<boxes.length}if(btn){btn.disabled=!checked.length;btn.textContent=`Delete Selected (${checked.length})`}};if(all)all.onchange=()=>{$$('.customer-select').forEach(x=>x.checked=all.checked);update()};$$('.customer-select').forEach(x=>x.onchange=update);update()}
function quotes(){return `<div class="card"><div class="card-head"><div class="toolbar"><input id="quoteSearch" placeholder="Search quote number or customer…"><select id="quoteStatus"><option value="">All statuses</option>${['Draft','Sent','Won','Paid','Lost'].map(s=>`<option>${s}</option>`).join('')}</select></div><button class="btn primary" onclick="newQuote()">+ Create Quote</button></div><div class="table-wrap"><table class="table"><thead><tr><th>Quote</th><th>Customer</th><th>Status</th><th>Total</th><th>Created</th><th>Valid until</th><th></th></tr></thead><tbody id="quoteRows">${quoteRows(state.data.quotes)}</tbody></table></div></div>`}
function quoteRows(list){return list.length?list.map(q=>`<tr><td><strong>${esc(q.quoteNumber)}</strong></td><td>${esc(q.customerName)}</td><td>${badge(q.status)}</td><td><strong>${money(q.total)}</strong></td><td>${dt(q.createdAt)}</td><td>${date(q.validUntil)}</td><td><button class="btn small" onclick="viewQuote('${q.id}')">Open</button><button class="btn small orange" onclick="sbcLoadQuoteToCart('${q.id}')">🛒 Build Order</button></td></tr>`).join(''):'<tr><td colspan="7"><div class="empty">No quotes yet.</div></td></tr>'}
function newQuote(){openModal('Create SBC quote',`<form id="quoteForm"><div class="form-grid"><label>Customer<select name="customerId" id="quoteCustomer"><option value="">Select customer</option>${state.data.customers.map(c=>`<option value="${c.id}" data-name="${esc(c.businessName||c.contactName)}">${esc(c.businessName||c.contactName)}</option>`).join('')}</select></label><label>Customer name<input name="customerName" id="quoteCustomerName" placeholder="Customer / business"></label><label>Status<select name="status"><option>Draft</option><option>Sent</option><option>Won</option><option>Paid</option><option>Lost</option></select></label><label>Valid until<input type="date" name="validUntil" value="${new Date(Date.now()+14*864e5).toISOString().slice(0,10)}"></label></div><div style="margin-top:18px"><div class="card-head" style="padding:0 0 10px;border:0"><h2>Line items</h2><button type="button" class="btn small" onclick="addQuoteLine()">+ Add item</button></div><div id="quoteItems" class="quote-items"></div></div><div class="form-grid" style="margin-top:15px"><label>Discount ($)<input id="quoteDiscount" name="discount" type="number" step="0.01" value="0"></label><label>Tax rate (%)<input id="quoteTax" name="taxRate" type="number" step="0.01" value="${Number(state.data.settings.taxRate||0)}"></label><label style="grid-column:1/-1">Notes<textarea name="notes" placeholder="Scope, turnaround, payment terms, etc."></textarea></label></div><div id="quoteTotals" class="quote-total"></div><div class="actions"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button class="btn primary">Save quote</button></div></form>`);addQuoteLine();$('#quoteCustomer').onchange=e=>{const o=e.target.selectedOptions[0];$('#quoteCustomerName').value=o?.dataset.name||''};$('#quoteDiscount').oninput=updateQuoteTotals;$('#quoteTax').oninput=updateQuoteTotals;$('#quoteForm').onsubmit=saveQuote}
function addQuoteLine(){const wrap=$('#quoteItems');if(!wrap)return;const quoteCatalog=[...state.catalog.packages,...state.catalog.services].filter(p=>state.me?.role==='owner'||!p.testOnly);const options=quoteCatalog.map(p=>`<option value="${esc(p.name)}" data-price="${p.price||0}" data-payment="${p.paymentUrl||''}">${esc(p.name)} — ${p.price?money(p.price):'Quote'}</option>`).join('');const row=document.createElement('div');row.className='quote-line';row.innerHTML=`<label>Item<select class="line-name">${options}<option value="Custom item" data-price="0">Custom item</option></select></label><label>Qty<input class="line-qty" type="number" min="1" value="1"></label><label>Unit price<input class="line-price" type="number" min="0" step="0.01" value="0"></label><div><div class="mini">Total</div><strong class="line-total">$0.00</strong></div><button type="button" class="icon-btn remove-line">×</button>`;wrap.appendChild(row);const s=row.querySelector('.line-name');s.onchange=()=>{const o=s.selectedOptions[0];row.querySelector('.line-price').value=o?.dataset.price||0;updateQuoteTotals()};row.querySelector('.line-qty').oninput=updateQuoteTotals;row.querySelector('.line-price').oninput=updateQuoteTotals;row.querySelector('.remove-line').onclick=()=>{row.remove();updateQuoteTotals()};s.dispatchEvent(new Event('change'))}
function quoteItems(){return $$('#quoteItems .quote-line').map(r=>({name:r.querySelector('.line-name').value||'Custom item',qty:Number(r.querySelector('.line-qty').value||1),unitPrice:Number(r.querySelector('.line-price').value||0),paymentUrl:r.querySelector('.line-name').selectedOptions[0]?.dataset.payment||''})).filter(x=>x.name)}
function updateQuoteTotals(){if(!$('#quoteItems'))return;const items=quoteItems(),sub=items.reduce((a,x)=>a+x.qty*x.unitPrice,0),disc=Number($('#quoteDiscount')?.value||0),rate=Number($('#quoteTax')?.value||0),tax=Math.max(0,sub-disc)*rate/100,total=Math.max(0,sub-disc)+tax;items.forEach((x,i)=>{const r=$$('#quoteItems .quote-line')[i];if(r)r.querySelector('.line-total').textContent=money(x.qty*x.unitPrice)});$('#quoteTotals').innerHTML=`<div class="total-row"><span>Subtotal</span><strong>${money(sub)}</strong></div><div class="total-row"><span>Discount</span><strong>-${money(disc)}</strong></div><div class="total-row"><span>Tax</span><strong>${money(tax)}</strong></div><div class="total-row grand"><span>Total</span><strong>${money(total)}</strong></div>`}
async function saveQuote(e){e.preventDefault();const p=Object.fromEntries(new FormData(e.target).entries());p.items=quoteItems();p.discount=Number(p.discount||0);p.taxRate=Number(p.taxRate||0);try{await api('/api/quotes',{method:'POST',body:JSON.stringify(p)});closeModal();await load();toast('Quote created')}catch(x){toast(x.message)}}
function sbcLoadQuoteToCart(id){
  const q=(state.data.quotes||[]).find(x=>x.id===id);
  if(!q){toast('Quote not found.');return;}
  const customer=(state.data.customers||[]).find(c=>c.id===q.customerId)||{};
  sbcSalesQuoteId=q.id;
  sbcSalesCart=(q.items||[]).map((x,i)=>{
    const catalog=(state.catalog?.packages||[]).concat(state.catalog?.services||[]);
    const match=catalog.find(p=>p.name===x.name);
    return {id:match?.id||`quote-${q.id}-${i+1}`,name:x.name,qty:Math.max(1,Number(x.qty||1)),unitPrice:Number(x.unitPrice||0),category:match?.category||'Quoted Service',paymentUrl:match?.paymentUrl||''};
  });
  state.view='salesorder';
  render();
  setTimeout(()=>{
    const picker=$('#sbcSalesCustomer');
    if(picker && q.customerId){picker.value=q.customerId;}
    const name=$('#sbcSalesCustomerName'); if(name)name.value=q.customerName||customer.businessName||customer.contactName||'';
    const contact=$('#sbcSalesContactName'); if(contact)contact.value=customer.contactName||'';
    const email=$('#sbcSalesCustomerEmail'); if(email)email.value=customer.email||'';
    const phone=$('#sbcSalesCustomerPhone'); if(phone)phone.value=customer.phone||'';
    const discount=$('#sbcSalesDiscount'); if(discount)discount.value=Number(q.discount||0).toFixed(2);
    const tax=$('#sbcSalesTax'); if(tax)tax.value=Number(q.taxRate||0).toFixed(2);
    sbcRenderSalesCart();
    toast(`${q.quoteNumber} loaded into the customer cart.`);
  },50);
}
function viewQuote(id){const q=state.data.quotes.find(x=>x.id===id);if(!q)return;openModal(q.quoteNumber,`<div class="quote-preview"><div class="q-head"><div class="q-logo"><img src="/assets/sbc-logo.jpg" alt="SBC"></div><div class="q-meta"><strong>QUOTE</strong><br>${esc(q.quoteNumber)}<br>Created ${dt(q.createdAt)}<br>${q.validUntil?`Valid until ${date(q.validUntil)}`:''}</div></div><div style="font-size:12px;margin-bottom:16px"><strong>Prepared for:</strong><br>${esc(q.customerName)}</div><table class="q-table"><thead><tr><th>Description</th><th>Qty</th><th>Unit</th><th>Total</th></tr></thead><tbody>${q.items.map(x=>`<tr><td>${esc(x.name)}</td><td>${x.qty}</td><td>${money(x.unitPrice)}</td><td>${money(x.qty*x.unitPrice)}</td></tr>`).join('')}</tbody></table><div class="q-foot"><div style="width:260px"><div class="total-row"><span>Subtotal</span><strong>${money(q.subtotal)}</strong></div><div class="total-row"><span>Discount</span><strong>-${money(q.discount)}</strong></div><div class="total-row"><span>Tax</span><strong>${money(q.tax)}</strong></div><div class="total-row grand"><span>Total</span><strong>${money(q.total)}</strong></div></div></div>${q.notes?`<div style="margin-top:22px"><strong style="font-size:11px">Notes</strong><div class="notes">${esc(q.notes)}</div></div>`:''}<div style="margin-top:24px;font-size:10px;color:var(--muted)">${esc(state.data.settings.businessName)} · ${esc(state.data.settings.phone)} · ${esc(state.data.settings.email)} · ${esc(state.data.settings.website)}</div></div><div class="actions no-print"><button class="btn" onclick="closeModal()">Close</button><button class="btn orange" onclick="sbcLoadQuoteToCart('${q.id}')">🛒 Build Order & Checkout</button><button class="btn primary" onclick="window.print()">Print / Save PDF</button>${q.paymentUrl?`<a class="btn orange" href="${q.paymentUrl}" target="_blank" rel="noopener">Pay via Square ↗</a>`:''}<select onchange="setQuoteStatus('${q.id}',this.value)"><option value="">Change status</option>${['Draft','Sent','Won','Paid','Lost'].map(s=>`<option>${s}</option>`).join('')}</select><button class="btn danger" onclick="deleteQuote('${q.id}')">Delete</button></div>`)}
async function setQuoteStatus(id,status){if(!status)return;try{await api('/api/quotes/'+id,{method:'PUT',body:JSON.stringify({status})});closeModal();await load();toast('Quote status updated')}catch(e){toast(e.message)}}
async function deleteQuote(id){if(!confirm('Delete this quote?'))return;try{await api('/api/quotes/'+id,{method:'DELETE'});closeModal();await load();toast('Quote deleted')}catch(e){toast(e.message)}}
function payments(){
/* SBC_V6613_SAFE_SQUARE_LINKS */
const links=state.data?.settings?.paymentLinks;
const checkoutLinks={};
if(links&&typeof links==='object'&&!Array.isArray(links)){
 for(const [key,value] of Object.entries(links)){try{
  const url=new URL(String(value||''));
  if(url.protocol!=='https:'||url.username||url.password)continue;
  if(!['square.link','checkout.square.site','square.site','squareup.com'].includes(url.hostname.toLowerCase()))continue;
  checkoutLinks[key]=url.href;
 }catch(_){}}
}
const anyCheckout=Object.keys(checkoutLinks).length>0;
const items=[['visibility','Business Visibility',99,'Entry online-presence service','No website included','Start here when the customer needs visibility help without a full website.'],['starter','SBC Business Starter',199,'Core business launch package','Website + core setup','For businesses that need the essential online foundation.'],['basic','Business Essentials',349,'Most Popular package','Website + stronger business setup','Recommended when the customer needs a more complete professional presence.'],['essentials','SBC Complete Business Launch',699,'Full launch package','Website + domain + protection + email + hosting + 500 cards','For customers who want SBC to handle the complete launch stack.'],['cards100','Business Cards — 100',40,'Print product','100 business cards','Quick standalone print purchase.'],['cards200','Business Cards — 200',50,'Print product','200 business cards','Quick standalone print purchase.'],['cards500','Business Cards — 500',75,'Print product','500 business cards','Useful for the $699 launch package or standalone print orders.'],['cards1000','Business Cards — 1,000',110,'Print product','1,000 business cards','High-volume standalone print purchase.']];return `<div class="hero"><div><div class="eyebrow" style="color:#f7a842">SQUARE PAYMENT CENTER</div><h2>Payment Center — choose the right checkout.</h2><p>Use the payment center to send the customer the correct Square checkout link. This screen is for checkout routing and internal sales support; it does not claim to be a live Square transaction feed.</p></div><div class="hero-actions"><button class="btn orange" onclick="state.view='quotes';render()">Open Quotes</button><button class="btn ghost" onclick="state.view='customers';render()">Open Customers</button></div></div><div class="grid four section">${items.slice(0,4).map(x=>`<div class="stat"><div class="label">${esc(x[1])}</div><div class="value">${money(x[2])}</div><div class="sub">${esc(x[3])}</div></div>`).join('')}</div><div class="card section"><div class="card-head"><div><h2>Customer checkout options</h2><div class="mini">Each card explains what the payment is for before the caller sends it.</div></div><span class="badge ${anyCheckout?'green':'orange'}">${anyCheckout?'CHECKOUT LINKS CONFIGURED':'SQUARE LINK SETUP NEEDED'}</span></div><div class="card-body"><div class="payment-grid">${items.map(x=>`<div class="payment-card"><span class="badge ${x[0].startsWith('cards')?'orange':'blue'}">${x[0].startsWith('cards')?'PRINT':'PACKAGE'}</span><h3>${esc(x[1])}</h3><div class="payment-price">${money(x[2])}</div><p><strong>Use for:</strong> ${esc(x[3])}</p><p class="mini"><strong>Includes / note:</strong> ${esc(x[4])}</p><p class="mini">${esc(x[5])}</p>${checkoutLinks[x[0]]?`<a class="btn primary wide" href="${esc(checkoutLinks[x[0]])}" target="_blank" rel="noopener noreferrer">Open Square Checkout ↗</a>`:`<span class="btn wide" role="status" aria-disabled="true">Square link not configured</span>`}</div>`).join('')}</div></div></div><div class="grid three section"><div class="card"><div class="card-head"><h2>Before payment</h2></div><div class="card-body"><ol class="feature-list"><li>Confirm the customer's business name.</li><li>Confirm the recommended package/product.</li><li>Confirm price and any applicable provider/tax/print charges.</li><li>Tell the customer the checkout link is secure Square checkout.</li></ol></div></div><div class="card"><div class="card-head"><h2>After payment</h2></div><div class="card-body"><ol class="feature-list"><li>Verify the order/quote is marked correctly.</li><li>Capture requirements and next steps.</li><li>Move the customer into onboarding/fulfillment.</li><li>Do not collect card numbers in the caller's notes.</li></ol></div></div><div class="card"><div class="card-head"><h2>What this screen does not show</h2></div><div class="card-body"><p class="mini">There is no live Square transaction API feed connected here. Actual transaction status should be verified in Square or the SBC order/quote record.</p><span class="badge orange">NO LIVE SQUARE TRANSACTION FEED</span></div></div></div>`}

async function runFullSystemTestOrder(){if(!confirm('Run the controlled SBC V47 full-cycle test? It creates a clearly labeled test customer/order and simulates a payment. No real charge or external vendor submission will occur.'))return;try{const r=await api('/api/owner/test-order/full-cycle',{method:'POST',body:'{}'});await load();toast(`TEST COMPLETE · ${r.order?.id||'order'} · ${r.verification?.processedJobs||0} fulfillment job processed`)}catch(e){toast('Test failed: '+e.message)}}
function orders(){const list=state.data.orders;return `<div class="card"><div class="card-head"><div class="toolbar"><input id="orderSearch" placeholder="Search customer or product…"><select id="orderStatus"><option value="">All statuses</option>${['New','Quoted','In Progress','Ready','Delivered','Cancelled'].map(s=>`<option>${s}</option>`).join('')}</select></div><div class="actions" style="margin:0"><button class="btn" onclick="runFullSystemTestOrder()">🧪 Run Full System Test</button><button class="btn primary" onclick="newOrder()">+ New Print Order</button></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Customer</th><th>Product</th><th>Qty</th><th>Status</th><th>Price</th><th>Profit</th><th>Created</th><th></th></tr></thead><tbody id="orderRows">${orderRows(list)}</tbody></table></div></div>`}
function orderRows(list){return list.length?list.map(o=>`<tr><td><strong>${esc(o.customerName)}</strong></td><td>${esc(o.product)}</td><td>${o.quantity}</td><td>${badge(o.status)}</td><td>${money(o.price)}</td><td class="profit">${money(o.price-o.cost)}</td><td>${dt(o.createdAt)}</td><td><button class="btn small" onclick="editOrder('${o.id}')">Open</button></td></tr>`).join(''):'<tr><td colspan="8"><div class="empty">No print orders yet.</div></td></tr>'}
function newOrder(existing={}){const o=existing;openModal(o.id?'Edit print order':'New print order',`<form id="orderForm"><div class="form-grid"><label>Customer<input name="customerName" value="${esc(o.customerName)}" required placeholder="Business / customer"></label><label>Product<input name="product" value="${esc(o.product)}" required placeholder="500 business cards"></label><label>Quantity<input type="number" min="1" name="quantity" value="${o.quantity||1}"></label><label>Status<select name="status">${['New','Quoted','In Progress','Ready','Delivered','Cancelled'].map(s=>`<option ${o.status===s?'selected':''}>${s}</option>`).join('')}</select></label><label>Your cost ($)<input type="number" step="0.01" name="cost" value="${o.cost||0}"></label><label>Customer price ($)<input type="number" step="0.01" name="price" value="${o.price||0}"></label><label style="grid-column:1/-1">Notes<textarea name="notes">${esc(o.notes)}</textarea></label></div><div class="actions"><button type="button" class="btn" onclick="closeModal()">Cancel</button>${o.id?`<button type="button" class="btn danger" onclick="deleteOrder('${o.id}')">Delete</button>`:''}<button class="btn primary">Save order</button></div></form>`);$('#orderForm').onsubmit=async e=>{e.preventDefault();const p=Object.fromEntries(new FormData(e.target).entries());p.quantity=Number(p.quantity||1);p.cost=Number(p.cost||0);p.price=Number(p.price||0);try{await api(o.id?'/api/orders/'+o.id:'/api/orders',{method:o.id?'PUT':'POST',body:JSON.stringify(p)});closeModal();await load();toast('Print order saved')}catch(x){toast(x.message)}}}
function editOrder(id){const o=state.data.orders.find(x=>x.id===id);if(o)newOrder(o)}
async function deleteOrder(id){if(!confirm('Delete this print order?'))return;try{await api('/api/orders/'+id,{method:'DELETE'});closeModal();await load();toast('Order deleted')}catch(e){toast(e.message)}}
function renewals(){const list=[...state.data.renewals].sort((a,b)=>String(a.dueDate).localeCompare(String(b.dueDate)));return `<div class="card"><div class="card-head"><div><h2>Renewals & recurring revenue</h2><div class="mini">Track domains, hosting, email and other repeat services.</div></div><button class="btn primary" onclick="newRenewal()">+ Add Renewal</button></div><div class="table-wrap"><table class="table"><thead><tr><th>Customer</th><th>Service</th><th>Due</th><th>Amount</th><th>Status</th><th></th></tr></thead><tbody>${list.length?list.map(r=>`<tr><td><strong>${esc(r.customerName)}</strong></td><td>${esc(r.service)}</td><td>${date(r.dueDate)}</td><td>${money(r.amount)}</td><td>${badge(r.status)}</td><td><button class="btn small" onclick="editRenewal('${r.id}')">Open</button></td></tr>`).join(''):'<tr><td colspan="6"><div class="empty">No renewals tracked yet.</div></td></tr>'}</tbody></table></div></div>`}
function newRenewal(existing={}){const r=existing;openModal(r.id?'Edit renewal':'Add renewal',`<form id="renewalForm"><div class="form-grid"><label>Customer<input name="customerName" value="${esc(r.customerName)}" required></label><label>Service<select name="service">${['Domain','Web Hosting','Business Email','Website Maintenance','Other'].map(s=>`<option ${r.service===s?'selected':''}>${s}</option>`).join('')}</select></label><label>Due date<input type="date" name="dueDate" value="${esc(r.dueDate||'')}" required></label><label>Amount ($)<input type="number" step="0.01" name="amount" value="${r.amount||0}"></label><label>Status<select name="status">${['Upcoming','Contacted','Paid','Overdue','Cancelled'].map(s=>`<option ${r.status===s?'selected':''}>${s}</option>`).join('')}</select></label><label>Notes<textarea name="notes">${esc(r.notes)}</textarea></label></div><div class="actions"><button type="button" class="btn" onclick="closeModal()">Cancel</button>${r.id?`<button type="button" class="btn danger" onclick="deleteRenewal('${r.id}')">Delete</button>`:''}<button class="btn primary">Save renewal</button></div></form>`);$('#renewalForm').onsubmit=async e=>{e.preventDefault();const p=Object.fromEntries(new FormData(e.target).entries());p.amount=Number(p.amount||0);try{await api(r.id?'/api/renewals/'+r.id:'/api/renewals',{method:r.id?'PUT':'POST',body:JSON.stringify(p)});closeModal();await load();toast('Renewal saved')}catch(x){toast(x.message)}}}
function editRenewal(id){const r=state.data.renewals.find(x=>x.id===id);if(r)newRenewal(r)}
async function deleteRenewal(id){if(!confirm('Delete this renewal?'))return;try{await api('/api/renewals/'+id,{method:'DELETE'});closeModal();await load();toast('Renewal deleted')}catch(e){toast(e.message)}}
function followups(){const c=[...state.data.customers].filter(x=>x.followUp).sort((a,b)=>String(a.followUp).localeCompare(String(b.followUp)));const overdue=c.filter(x=>x.followUp<today()).length,next=c.filter(x=>x.followUp>=today()&&x.followUp<=new Date(Date.now()+7*864e5).toISOString().slice(0,10)).length;return `<div class="card section"><div class="card-head"><div><h2>👥 Internal Employee Email</h2><div class="mini">Send directly to SBC employees without creating customer records.</div></div><span class="badge blue">INTERNAL</span></div><div class="card-body"><div class="list-card"><div><strong>Employee directory</strong><div class="meta">Authorized employees can be emailed directly from their employee records.</div></div><div class="actions" style="margin:0"><button class="btn small primary" onclick="openEmployeeEmailPicker()">✉️ Email Employee</button></div></div></div></div><div class="grid stats"><div class="stat"><div class="label">TOTAL</div><div class="value">${c.length}</div><div class="sub">Scheduled next actions</div></div><div class="stat"><div class="label">OVERDUE</div><div class="value">${overdue}</div><div class="sub">Call these first</div></div><div class="stat"><div class="label">NEXT 7 DAYS</div><div class="value">${next}</div><div class="sub">Upcoming follow-ups</div></div><div class="stat"><div class="label">LEADS</div><div class="value">${state.data.customers.filter(x=>x.status==='Lead').length}</div><div class="sub">Active opportunities</div></div><div class="stat"><div class="label">TIP</div><div class="value" style="font-size:18px">Follow up fast</div><div class="sub">The money is usually in the next conversation.</div></div></div><div class="card section"><div class="card-head"><h2>Follow-up queue</h2><span class="badge orange">${overdue} overdue</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Date</th><th>Business</th><th>Contact</th><th>Status</th><th>Phone</th><th></th></tr></thead><tbody>${c.length?c.map(x=>`<tr><td><strong>${date(x.followUp)}</strong></td><td>${esc(x.businessName||'—')}</td><td>${esc(x.contactName||'—')}</td><td>${badge(x.status)}</td><td>${esc(x.phone||'—')}</td><td><button class="btn small" onclick="editCustomer('${x.id}')">Open</button></td></tr>`).join(''):'<tr><td colspan="6"><div class="empty">No follow-ups scheduled.</div></td></tr>'}</tbody></table></div></div>`}
function catalog(){return `<div class="card"><div class="card-head"><div><h2>SBC Price Book</h2><div class="mini">Customer-facing packages and print pricing.</div></div><a class="btn" href="https://sbcmia.com" target="_blank" rel="noopener">Open SBC website ↗</a></div><div class="card-body"><div class="grid catalog-grid">${(Array.isArray(state.catalog?.packages)?state.catalog.packages:[]).map(p=>`<div class="card price-card"><span class="badge blue">PACKAGE</span><h3>${esc(p.name)}</h3><div class="price">${money(p.price)}</div>${p.value?`<div class="mini" style="color:var(--green);font-weight:800;margin-top:4px">Package value ${money(p.value)}+</div>`:''}<p class="mini">${esc(p.description)}</p><ul class="feature-list">${p.features.map(f=>`<li>${esc(f)}</li>`).join('')}</ul><a class="btn primary wide" href="${p.paymentUrl}" target="_blank" rel="noopener">Square Checkout ↗</a></div>`).join('')}</div><h3 style="margin-top:26px">Individual services & print</h3><div class="table-wrap"><table class="table"><thead><tr><th>Service</th><th>Category</th><th>Customer price</th><th>Pricing</th></tr></thead><tbody>${state.catalog.services.map(s=>`<tr><td><strong>${esc(s.name)}</strong></td><td>${esc(s.category)}</td><td>${s.price?money(s.price):'Quote'}</td><td>${s.unit==='set'?'Per set':'Custom scope'}</td></tr>`).join('')}</tbody></table></div></div></div>`}
function presentation(){const s=state.data.settings;const packs=state.catalog.packages;return `<div class="presentation"><div class="presentation-head"><div class="presentation-brand"><img src="/assets/sbc-logo.jpg" alt="Successful By Choice"><div><strong>${esc(s.businessName)}</strong><span>${esc(s.tagline)} · ${esc(s.slogan)}</span></div></div><div class="actions" style="margin:0"><button class="btn" onclick="window.print()">Print / Save PDF</button><button class="btn primary" onclick="shareSBC()">Share</button><button class="btn" onclick="state.view='dashboard';render()">Exit Customer Mode</button></div></div><div class="hero" style="margin-bottom:20px"><div><div class="eyebrow" style="color:#f7a842">WELCOME TO SUCCESSFUL BY CHOICE</div><h2>Professional tools for businesses ready to look the part and grow.</h2><p>Websites, hosting, business email, visibility, printing and practical business support — all in one place.</p></div></div><div class="presentation-grid">${packs.map((p,i)=>`<div class="presentation-card ${i===2?'featured':''}"><span class="badge ${i===2?'green':'blue'}">${i===2?'BEST VALUE':'SBC PACKAGE'}</span><h3>${esc(p.name)}</h3><div class="price">${money(p.price)}</div><p>${esc(p.description)}</p><ul class="feature-list">${p.features.slice(0,6).map(f=>`<li>${esc(f)}</li>`).join('')}</ul><a class="btn primary wide" href="${p.paymentUrl}" target="_blank" rel="noopener">Choose ${esc(p.name)} ↗</a></div>`).join('')}</div><div class="grid three section"><div class="card"><div class="card-body"><strong>Web & Hosting</strong><p class="mini">Domains, hosting, websites, SSL, business email and ongoing support.</p></div></div><div class="card"><div class="card-body"><strong>Visibility & Marketing</strong><p class="mini">Google Business, social setup, flyers, menus and other customer-facing materials.</p></div></div><div class="card"><div class="card-body"><strong>Print</strong><p class="mini">Business cards and marketing print with simple, transparent customer pricing.</p></div></div></div><div class="presentation-footer">${esc(s.businessName)} · ${esc(s.phone)} · ${esc(s.email)} · ${esc(s.city)}<br><strong>${esc(s.slogan)}</strong></div></div>`}
async function shareSBC(){const s=state.data.settings;const data={title:s.businessName,text:`${s.businessName} — ${s.tagline}`,url:s.website};try{if(navigator.share)await navigator.share(data);else{await navigator.clipboard.writeText(s.website);toast('SBC website link copied')}}catch(e){}}
function reports(){const d=state.data,q=d.quotes,o=d.orders,r=d.renewals;const won=q.filter(x=>['Won','Paid'].includes(x.status)),revenue=won.reduce((a,x)=>a+x.total,0),quoted=q.reduce((a,x)=>a+x.total,0),profit=o.reduce((a,x)=>a+x.price-x.cost,0),conversion=q.length?Math.round(won.length/q.length*100):0;const bySource={};d.customers.forEach(c=>bySource[c.source]=(bySource[c.source]||0)+1);return `<div class="card section"><div class="card-head"><div><h2>👥 Internal Employee Email</h2><div class="mini">Send directly to SBC employees without creating customer records.</div></div><span class="badge blue">INTERNAL</span></div><div class="card-body"><div class="list-card"><div><strong>Employee directory</strong><div class="meta">Authorized employees can be emailed directly from their employee records.</div></div><div class="actions" style="margin:0"><button class="btn small primary" onclick="openEmployeeEmailPicker()">✉️ Email Employee</button></div></div></div></div><div class="grid stats"><div class="stat"><div class="label">QUOTED VALUE</div><div class="value">${money(quoted)}</div><div class="sub">All quotes</div></div><div class="stat"><div class="label">WON / PAID</div><div class="value">${money(revenue)}</div><div class="sub">Closed quote value</div></div><div class="stat"><div class="label">QUOTE CONVERSION</div><div class="value">${conversion}%</div><div class="sub">Won or paid / all quotes</div></div><div class="stat"><div class="label">PRINT PROFIT</div><div class="value">${money(profit)}</div><div class="sub">Recorded order margin</div></div><div class="stat"><div class="label">RENEWAL VALUE</div><div class="value">${money(r.filter(x=>x.status!=='Paid'&&x.status!=='Cancelled').reduce((a,x)=>a+x.amount,0))}</div><div class="sub">Open recurring opportunities</div></div></div><div class="grid two section"><div class="card"><div class="card-head"><h2>Lead sources</h2></div><div class="card-body">${Object.entries(bySource).sort((a,b)=>b[1]-a[1]).map(([k,v])=>`<div style="display:flex;justify-content:space-between;padding:10px 0;border-bottom:1px solid var(--line);font-size:12px"><span>${esc(k)}</span><strong>${v}</strong></div>`).join('')||'<div class="empty">Add customers to see source performance.</div>'}</div></div><div class="card"><div class="card-head"><h2>Quote status</h2></div><div class="card-body">${['Draft','Sent','Won','Paid','Lost'].map(s=>{const a=q.filter(x=>x.status===s);return `<div style="display:flex;justify-content:space-between;padding:10px 0;border-bottom:1px solid var(--line);font-size:12px"><span>${s}</span><strong>${a.length} · ${money(a.reduce((v,x)=>v+x.total,0))}</strong></div>`}).join('')}</div></div></div><div class="card section"><div class="card-head"><h2>Export your business data</h2><span class="badge green">Backup</span></div><div class="card-body"><p class="mini">Download a complete JSON backup of customers, quotes, orders, renewals, settings and activity. Keep a copy somewhere safe.</p><a class="btn primary" href="/api/export">Download SBC backup</a></div></div>`}
function settings(){const s=state.data.settings;return `<div class="grid two"><div class="card"><div class="card-head"><h2>Business profile</h2></div><div class="card-body"><form id="settingsForm"><div class="form-grid"><label>Business name<input name="businessName" value="${esc(s.businessName)}"></label><label>Tagline<input name="tagline" value="${esc(s.tagline)}"></label><label>Slogan<input name="slogan" value="${esc(s.slogan)}"></label><label>Phone<input name="phone" value="${esc(s.phone)}"></label><label>Email<input name="email" value="${esc(s.email)}"></label><label>City<input name="city" value="${esc(s.city)}"></label><label>Office<input name="office" value="${esc(s.office)}"></label><label>Website<input name="website" value="${esc(s.website)}"></label><label>SBC Websites<input name="websites" value="${esc(s.websites)}"></label><label>Default tax rate (%)<input name="taxRate" type="number" step="0.01" value="${Number(s.taxRate||0)}"></label><label>Quote prefix<input name="quotePrefix" value="${esc(s.quotePrefix)}"></label><label>CRM API key<input name="crmApiKey" value="${esc(s.crmApiKey||'') }" placeholder="Optional inbound lead key"></label><label style="display:flex;align-items:center;gap:10px;flex-direction:row"><input name="automationEnabled" type="checkbox" ${s.automationEnabled!==false?'checked':''}> Enable automatic follow-up sequences</label></div><div class="actions"><button class="btn primary">Save profile</button></div></form></div></div><div class="card"><div class="card-head"><h2>Command Center Appearance</h2><span class="badge blue">LOCAL</span></div><div class="card-body"><div class="list-card"><div><strong>Theme</strong><div class="meta">Choose how your private Command Center looks on this device.</div></div><select id="sbcThemeSelect" onchange="applySbcTheme(this.value)" style="min-width:130px"><option value="light">☀️ Light</option><option value="dark">🌙 Dark</option></select></div><div class="mini">Your choice is saved in this browser and does not change the SBC data or employee permissions.</div></div></div><div class="card"><div class="card-head"><h2>Production & data</h2></div><div class="card-body"><div class="list-card"><div><div class="title">Storage</div><div class="meta">${state.data.storage.startsWith('mysql')?'MySQL database':'Persistent app file'}</div></div><span class="badge green">Active</span></div><div class="list-card"><div><div class="title">Authentication</div><div class="meta">HttpOnly signed session cookie</div></div><span class="badge green">Protected</span></div><div class="list-card"><div><div class="title">Admin secret</div><div class="meta">Configured in GoDaddy Secrets</div></div><span class="badge blue">Server-side</span></div><div class="install-tip">📱 <strong>Phone-ready:</strong> This app includes a mobile layout and installable web-app support. On iPhone, open it in Safari → Share → Add to Home Screen. On Android, use the browser menu → Install app.</div><div class="actions"><a class="btn" href="/api/export">Download backup</a><label class="btn" style="cursor:pointer">Import backup<input id="importFile" type="file" accept="application/json" hidden></label></div><p class="mini" style="margin-top:15px">For the strongest production setup, configure GoDaddy MySQL using the environment variables listed in the README. The app automatically uses MySQL when all database variables are present and falls back to its persistent file storage when they are not.</p></div></div></div>`}
function bindView(){const portalQuick=$('#portalCustomerQuickList');if(portalQuick&&!portalQuick.dataset.bound){portalQuick.dataset.bound='1';portalQuick.addEventListener('click',e=>{const b=e.target.closest('.portal-customer-open');if(!b)return;openPortalCustomerDirect(b.dataset.customerId);});}const pcs=$('#portalCustomerSearch');if(pcs){pcs.oninput=()=>{const q=pcs.value.toLowerCase().trim();const list=state.data.customers||[];const box=$('#portalCustomerQuickList');if(box)box.innerHTML=list.filter(c=>`${c.businessName||''} ${c.contactName||''} ${c.phone||''} ${c.email||''}`.toLowerCase().includes(q)).slice(0,20).map(c=>`<button type="button" class="list-card" style="text-align:left;cursor:pointer" onclick="openPortalCustomerDirect('${esc(c.id)}')"><div><strong>${esc(c.businessName||c.contactName||'Customer')}</strong><div class="meta">${esc(c.contactName||'')} · ${esc(c.phone||'No phone')}</div></div><span class="badge blue">OPEN</span></button>`).join('')||'<div class="empty">No matching customer.</div>';}}const cs=$('#customerSearch'),cst=$('#customerStatus');if(cs){const ct=$('#customerTemperature');const run=()=>{$('#customerRows').innerHTML=customerRows(state.data.customers.filter(c=>(!cst.value||c.status===cst.value)&&(!ct?.value||c.leadTemperature===ct.value)&&(`${c.businessName} ${c.contactName} ${c.phone} ${c.email} ${c.website} ${c.industry}`).toLowerCase().includes(cs.value.toLowerCase())))};cs.oninput=run;cst.onchange=run;if(ct)ct.onchange=run}const qs=$('#quoteSearch'),qst=$('#quoteStatus');if(qs){const run=()=>{$('#quoteRows').innerHTML=quoteRows(state.data.quotes.filter(q=>(!qst.value||q.status===qst.value)&&(`${q.quoteNumber} ${q.customerName}`).toLowerCase().includes(qs.value.toLowerCase())))};qs.oninput=run;qst.onchange=run}const os=$('#orderSearch'),ost=$('#orderStatus');if(os){const run=()=>{$('#orderRows').innerHTML=orderRows(state.data.orders.filter(o=>(!ost.value||o.status===ost.value)&&(`${o.customerName} ${o.product}`).toLowerCase().includes(os.value.toLowerCase())))};os.oninput=run;ost.onchange=run}const sf=$('#settingsForm');if(sf)sf.onsubmit=async e=>{e.preventDefault();const p=Object.fromEntries(new FormData(sf).entries());p.taxRate=Number(p.taxRate||0);p.automationEnabled=Boolean(sf.elements.automationEnabled?.checked);try{await api('/api/settings',{method:'PUT',body:JSON.stringify(p)});await load();toast('Business profile saved')}catch(x){toast(x.message)}};const imp=$('#importFile');if(imp)imp.onchange=async e=>{const f=e.target.files[0];if(!f)return;try{const data=JSON.parse(await f.text());if(!confirm('Import this backup? This will replace the current workspace data.'))return;await api('/api/import',{method:'POST',body:JSON.stringify(data)});await load();toast('Backup imported')}catch(x){toast('Import failed: '+x.message)}}}
// V55.10.1 navigation hardening: use the canonical V9 router when present.
// Bind directly to each sidebar item so a later global click handler cannot strand navigation.
function sbcNavigate(view){
    const b=[...document.querySelectorAll('.nav-item[data-view]')].find(x=>x.dataset.view===view);
  // Programmatic/quick-action buttons are valid navigation targets even when
  // the destination is not represented by a sidebar item. Only block a route
  // when a real sidebar item exists and is explicitly hidden.
  if(b && b.style.display==='none') return;
  state.view=view;
  document.querySelectorAll('.nav-item[data-view]').forEach(x=>x.classList.toggle('active',x.dataset.view===view));
  document.querySelector('.sidebar')?.classList.remove('open');
  return render();
}
window.sbcNavigate=sbcNavigate;
function bindSbcPrimaryNav(){
  document.querySelectorAll('.sidebar .nav-item[data-view]').forEach(b=>{
    if(b.dataset.sbcNavBound==='1') return;
    b.dataset.sbcNavBound='1';
    b.type='button';
    b.onclick=()=>sbcNavigate(b.dataset.view);
  });
}
$('#mobileMenu').onclick=()=>$('.sidebar').classList.toggle('open');$('#modalClose').onclick=closeModal;$('.modal-backdrop').onclick=closeModal;$('#logoutBtn').onclick=async()=>{const b=$('#logoutBtn');if(b)b.disabled=true;try{await api('/api/logout',{method:'POST',timeoutMs:15000});try{localStorage.removeItem('sbc-client-version');}catch(e){};location.replace('/');}catch(e){if(b)b.disabled=false;toast(e.message||'Sign out failed.');}};$('#loginForm').onsubmit=async e=>{e.preventDefault();$('#loginError').textContent='';try{let r;let lastErr;for(let attempt=0;attempt<2;attempt++){try{r=await api('/api/login',{method:'POST',body:JSON.stringify({username:$('#loginUsername').value,password:$('#loginPassword').value}),timeoutMs:20000});break}catch(err){lastErr=err;if(attempt===0)await new Promise(resolve=>setTimeout(resolve,900));}}if(!r)throw lastErr||new Error('SBC sign-in request failed.');await boot()}catch(x){$('#loginError').textContent=x.message}};
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();state.installPrompt=e});
function globalSearch(q){q=q.trim().toLowerCase();if(!q)return;const d=state.data||{};const hits=[...(d.customers||[]).map(x=>({kind:'Customer',label:x.businessName||x.contactName,id:x.id,view:'customers'})),...(d.quotes||[]).map(x=>({kind:'Quote',label:x.quoteNumber+' · '+x.customerName,id:x.id,view:'quotes'})),...(d.orders||[]).map(x=>({kind:'Print',label:x.customerName+' · '+x.product,id:x.id,view:'orders'}))].filter(x=>x.label.toLowerCase().includes(q)).slice(0,8);if(!hits.length){toast('No matching SBC record');return}openModal('Search results',hits.map(h=>`<button class="list-card" style="width:100%;border:0;background:#fff;text-align:left;cursor:pointer" onclick="state.view='${h.view}';closeModal();render();${h.view==='customers'?`setTimeout(()=>editCustomer('${h.id}'),50)`:h.view==='quotes'?`setTimeout(()=>viewQuote('${h.id}'),50)`:''}"><div><div class="title">${esc(h.kind)}</div><div class="meta">${esc(h.label)}</div></div><span class="badge blue">Open</span></button>`).join(''))}
const gs=$('#globalSearch');if(gs){gs.addEventListener('keydown',e=>{if(e.key==='Enter')globalSearch(gs.value)});window.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();gs.focus()}})}
