async function resetEmployeeOnboarding(id){if(!confirm('Reset this employee onboarding to the beginning? Customer/lead records and assignments will be preserved.'))return;try{await api('/api/v9/onboarding/'+encodeURIComponent(id)+'/reset',{method:'POST',body:'{}'});await load();toast('Onboarding reset to Not Started ✓')}catch(e){toast(e.message)}}
function onboardingRecordForUser(id){const uid=String(id||'');if(!uid)return null;const own=state.me?.id&&String(state.me.id)===uid?state.data.onboarding:null;if(own)return {user:state.me,onboarding:{...own}};return (state.data.onboardingRoster||[]).find(x=>String(x.user?.id)===uid)||null}
function openOnboarding(id){const r=onboardingRecordForUser(id);if(!r){toast('Your onboarding record is still loading. Refresh once and try again.');return;}const u=r.user||{},o={...(r.onboarding||{})};const ownUser=String(state.me?.id||'')===String(u.id||id);openModal(`Onboarding · ${esc(u.name||state.me?.name||'Team Member')}`,`<form id="onboardForm" novalidate><div id="onboardFormStatus" class="mini" style="margin-bottom:12px">${esc(o.status||'Not Started')} · You can save incomplete information and return to finish it.</div><div class="form-grid"><label>Legal name<input name="legalName" value="${esc(o.legalName||u.name||'')}"></label><label>Preferred name<input name="preferredName" value="${esc(o.preferredName||'')}"></label><label>Email<input name="email" type="email" value="${esc(o.email||u.profile?.email||'')}"></label><label>Phone<input name="phone" value="${esc(o.phone||'')}"></label><label>Address<input name="address" value="${esc(o.address||'')}"></label><label>City<input name="city" value="${esc(o.city||'')}"></label><label>Region/State<input name="region" value="${esc(o.region||'')}"></label><label>Postal code<input name="postalCode" value="${esc(o.postalCode||'')}"></label><label>Country<input name="country" value="${esc(o.country||'Philippines')}"></label><label>Timezone<input name="timezone" value="${esc(o.timezone||'')}"></label><label>Remote location<input name="remoteLocation" value="${esc(o.remoteLocation||'')}"></label><label>Payment method<input name="paymentMethod" value="${esc(o.paymentMethod||'OnlineJobs.ph EasyPay')}"></label>${u.role==='caller'?`<label>Headset / headphones<input name="headsetConfirmed" value="${esc(o.headsetConfirmed?'Confirmed':'')}" placeholder="Confirm working headset for SBC calls"></label>`:''}</div><div class="onboard-consents"><label><input type="checkbox" name="contractorAgreementAccepted" ${o.contractorAgreementAccepted?'checked':''}> Contractor agreement accepted</label><label><input type="checkbox" name="confidentialityAccepted" ${o.confidentialityAccepted?'checked':''}> Confidentiality accepted</label><label><input type="checkbox" name="codeOfConductAccepted" ${o.codeOfConductAccepted?'checked':''}> Code of conduct accepted</label><label><input type="checkbox" name="remoteLocationConfirmed" ${o.remoteLocationConfirmed?'checked':''}> Remote work location confirmed</label></div><label>Notes<textarea name="notes">${esc(o.notes||'')}</textarea></label><p class="mini">${ownUser?'Your information saves immediately. Owner verification is separate and cannot be self-approved.':'Owner verification is separate and cannot be self-approved.'}</p><div class="actions"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button type="submit" class="btn primary" id="completeOnboardingBtn">Save Onboarding</button></div></form>`);bindOnboardingFormSave(id)}
async function submitOnboardingForm(id){
  const form=$('#onboardForm');
  if(!form)return;
  const btn=$('#completeOnboardingBtn'),status=$('#onboardFormStatus');
  const fd=new FormData(form),b=Object.fromEntries(fd.entries());
  for(const k of ['contractorAgreementAccepted','confidentialityAccepted','codeOfConductAccepted','remoteLocationConfirmed'])b[k]=fd.has(k);
  if(btn){btn.disabled=true;btn.textContent='Saving…';}
  try{
    const saved=await api('/api/v9/onboarding/'+encodeURIComponent(id),{method:'PUT',body:JSON.stringify(b),timeoutMs:30000});
    // Update the authoritative local onboarding record without reloading the whole application.
    if(state.data){
      if(state.me?.id && String(state.me.id)===String(id)){
        state.data.onboarding={...saved};
      }
      if(Array.isArray(state.data.onboardingRoster)){
        const row=state.data.onboardingRoster.find(x=>String(x.user?.id)===String(id));
        if(row)row.onboarding={...saved};
      }
    }
    if(status)status.textContent=`Saved successfully · ${saved.status||'Incomplete'}`;
    if(btn){btn.disabled=false;btn.textContent='Save Onboarding';}
    toast(saved.status==='Pending Owner Verification'?'Onboarding saved — pending Romeo’s verification':'Onboarding saved ✓');
    // Keep the employee in the modal so partial onboarding can continue safely.
    if(state.me?.id && String(state.me.id)===String(id))render();
  }catch(x){
    if(status)status.textContent=`Save failed: ${x.message||'Unknown error'}`;
    toast(x.message||'Onboarding could not be saved.');
    if(btn){btn.disabled=false;btn.textContent='Save Onboarding';}
  }
}

function editMyOnboarding(){const id=state.me?.id;if(!id){toast('Your employee account could not be identified.');return;}openOnboarding(id)}

// V55.17.6: bind the onboarding save action to the form itself and update local state in-place.
// Do not re-bootstrap the entire Command Center after a save; a full reload could replace the
// modal DOM while the employee is editing and made the save appear to flash to a blank screen.
function bindOnboardingFormSave(id){const form=$('#onboardForm');if(!form)return false;form.onsubmit=(e)=>{e.preventDefault();submitOnboardingForm(id);return false;};return true}

