(function(){function prune(){try{document.querySelectorAll('button,a,[role=button],input[type=button],input[type=submit]').forEach(function(el){var label=[el.innerText,el.textContent,el.getAttribute('aria-label'),el.getAttribute('title'),el.value].filter(Boolean).join(' ').toLowerCase();if(/force.?unlock|recovery.?lock|recovery.?unlock/.test(label))el.remove();});}catch(_){}}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',prune,{once:true});else prune();try{new MutationObserver(prune).observe(document.documentElement,{subtree:true,childList:true});}catch(_){}})();

